package com.sendw.mpos.imports.infrastructure;
import com.sendw.mpos.imports.application.ImportRepository;
import com.sendw.mpos.shared.domain.Validation;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
@org.springframework.stereotype.Repository
public class JdbcImportRepository implements ImportRepository {
 private final JdbcTemplate db;public JdbcImportRepository(JdbcTemplate db){this.db=db;}
 private Map<String,Object> one(List<Map<String,Object>> rows){if(rows.isEmpty())throw Validation.missing();return rows.getFirst();}
 public Map<String,Object> lookups(){return Map.of("products",db.queryForList("SELECT p.id,p.name,p.code,u.name unit_name FROM products p JOIN units u ON u.id=p.product_unit ORDER BY p.name"),"warehouses",db.queryForList("SELECT id,name FROM warehouses ORDER BY name"),"customers",db.queryForList("SELECT id,name FROM customers ORDER BY name"),"partners",partners());}
 public List<Map<String,Object>> partners(){return db.queryForList("SELECT * FROM import_partners ORDER BY name,id");}
 public Map<String,Object> partner(long id){return one(db.queryForList("SELECT * FROM import_partners WHERE id=? FOR SHARE",id));}
 public long savePartner(Long id,Map<String,Object>b){if(id==null)return db.queryForObject("INSERT INTO import_partners(name,kind,phone,email,address) VALUES(?,?,?,?,?) RETURNING id",Long.class,b.get("name"),b.get("kind"),b.get("phone"),b.get("email"),b.get("address"));if(db.update("UPDATE import_partners SET name=?,phone=?,email=?,address=? WHERE id=? AND kind=?",b.get("name"),b.get("phone"),b.get("email"),b.get("address"),id,b.get("kind"))!=1)throw Validation.invalid("Partner type cannot be changed");return id;}
 public List<Map<String,Object>> list(int page,String search){return db.queryForList("SELECT s.*,a.name shipping_agent_name,t.name transport_agent_name,w.name warehouse_name FROM import_shipments s JOIN import_partners a ON a.id=s.shipping_agent_id JOIN import_partners t ON t.id=s.transport_agent_id JOIN warehouses w ON w.id=s.warehouse_id WHERE (s.booking_number ILIKE ? OR s.shipment_number ILIKE ?) ORDER BY s.id DESC LIMIT 20 OFFSET ?",search,search,(page-1L)*20);}
 public long count(String search){return db.queryForObject("SELECT count(*) FROM import_shipments WHERE booking_number ILIKE ? OR shipment_number ILIKE ?",Long.class,search,search);}
 public Map<String,Object> shipment(long id,boolean lock){return one(db.queryForList("SELECT s.*,a.name shipping_agent_name,t.name transport_agent_name,w.name warehouse_name FROM import_shipments s JOIN import_partners a ON a.id=s.shipping_agent_id JOIN import_partners t ON t.id=s.transport_agent_id JOIN warehouses w ON w.id=s.warehouse_id WHERE s.id=?"+(lock?" FOR UPDATE OF s":""),id));}
 public long saveShipment(Long id,Map<String,Object>b,long actor){Object[] args={b.get("date"),b.get("booking_number"),b.get("shipping_agent_id"),b.get("transport_agent_id"),b.get("warehouse_id"),b.get("expected_containers"),b.get("booking_confirmation_ref"),b.get("notes")};if(id==null){var a=new ArrayList<Object>(Arrays.asList(args));a.add(actor);return db.queryForObject("INSERT INTO import_shipments(date,booking_number,shipping_agent_id,transport_agent_id,warehouse_id,expected_containers,booking_confirmation_ref,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.toArray());}var a=new ArrayList<Object>(Arrays.asList(args));a.add(id);db.update("UPDATE import_shipments SET date=?,booking_number=?,shipping_agent_id=?,transport_agent_id=?,warehouse_id=?,expected_containers=?,booking_confirmation_ref=?,notes=?,version=version+1 WHERE id=?",a.toArray());return id;}
 public void replaceContainers(long id,List<Map<String,Object>> rows){db.update("DELETE FROM import_containers WHERE shipment_id=?",id);for(var r:rows)db.update("INSERT INTO import_containers(shipment_id,container_number,product_id,unit_id,unit_name,pieces,weight_kg) VALUES(?,?,?,?,?,?,?)",id,r.get("container_number"),r.get("product_id"),r.get("unit_id"),r.get("unit_name"),r.get("pieces"),r.get("weight_kg"));}
 public List<Map<String,Object>> containers(long id){return db.queryForList("SELECT c.*,p.name product_name,p.code product_code,p.product_price,c.pieces-COALESCE((SELECT sum(a.pieces) FROM import_sale_allocations a JOIN sales s ON s.id=a.sale_id WHERE a.container_id=c.id AND s.status<>4),0) remaining_pieces FROM import_containers c JOIN products p ON p.id=c.product_id WHERE c.shipment_id=? ORDER BY c.id",id);}
 public Map<String,Object> product(long id){return one(db.queryForList("SELECT p.id,p.product_unit,u.name unit_name FROM products p JOIN units u ON u.id=p.product_unit WHERE p.id=? FOR SHARE OF p,u",id));}
 public void receive(long id){db.update("UPDATE import_shipments SET status='received',received_at=now(),version=version+1 WHERE id=?",id);}
 public void cancel(long id){db.update("UPDATE import_shipments SET status='cancelled',version=version+1 WHERE id=?",id);}
 public List<Map<String,Object>> expenses(long id){return db.queryForList("SELECT e.*,f.id file_id,f.filename FROM import_expenses e LEFT JOIN import_files f ON f.expense_id=e.id WHERE e.shipment_id=? ORDER BY e.id DESC",id);}
 public long addExpense(long id,Map<String,Object>b){return db.queryForObject("INSERT INTO import_expenses(shipment_id,date,kind,invoice_number,description,currency,amount,rate_to_sar,amount_sar) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,id,b.get("date"),b.get("kind"),b.get("invoice_number"),b.get("description"),b.get("currency"),b.get("amount"),b.get("rate_to_sar"),b.get("amount_sar"));}
 public void removeExpense(long shipment,long expense){db.update("DELETE FROM import_files WHERE shipment_id=? AND expense_id=?",shipment,expense);db.update("DELETE FROM import_expenses WHERE shipment_id=? AND id=?",shipment,expense);}
 public void addFile(UUID id,long shipment,Long expense,String kind,ImportFile f){db.update("INSERT INTO import_files(id,shipment_id,expense_id,kind,filename,mime,content) VALUES(?,?,?,?,?,?,?)",id,shipment,expense,kind,f.filename(),f.mime(),f.content());}
 public List<Map<String,Object>> files(long shipment){return db.queryForList("SELECT id,kind,filename,mime,created_at,octet_length(content) size FROM import_files WHERE shipment_id=? AND expense_id IS NULL ORDER BY created_at DESC",shipment);}
 public ImportFile file(long shipment,UUID id){var r=one(db.queryForList("SELECT filename,mime,content FROM import_files WHERE shipment_id=? AND id=?",shipment,id));return new ImportFile((String)r.get("filename"),(String)r.get("mime"),(byte[])r.get("content"));}
 public void removeFile(long shipment,UUID id){db.update("DELETE FROM import_files WHERE shipment_id=? AND id=? AND expense_id IS NULL",shipment,id);}
 public void allocate(long container,long sale,long pieces){db.update("INSERT INTO import_sale_allocations(container_id,sale_id,pieces) VALUES(?,?,?)",container,sale,pieces);}
 public List<Map<String,Object>> sales(long shipment){return db.queryForList("SELECT DISTINCT s.id,s.date,s.status,s.grand_total,s.currency_symbol,s.currency_code,c.name customer_name FROM sales s JOIN import_sale_allocations a ON a.sale_id=s.id JOIN import_containers k ON k.id=a.container_id JOIN customers c ON c.id=s.customer_id WHERE k.shipment_id=? ORDER BY s.id DESC",shipment);}
 public void setSaleCurrency(long id,String currency,String symbol){db.update("UPDATE sales SET currency_code=?,currency_symbol=? WHERE id=?",currency,symbol,id);}
}
